"""Typed campaign records and the publication/revision ledger.

A capture row is validated against PROTOCOL.md; a row that fails any logical
rule is rejected (its ``[capture, ordinal]`` index is reported) while the
envelope stays valid.  Valid rows are reduced to a hashable *content* tuple so
that revision reconciliation can collapse identical semantic contents while
ignoring publication time and address/integer/base64 spelling.
"""
from common import (Invalid, MAX_TIME, address, decode64, decimal, ident)
from protocols import signature

REVISION_MAX = 10**9
ATTEMPT_MAX = 10**6
PAYLOAD_MAX = 65536
ICMP_RESULTS = frozenset(('echo', 'error', 'timeout'))
APP_RESULTS = frozenset(('open', 'closed', 'timeout'))
TCP_SIGNATURE = ('tcp',)
DELETE = ('d',)


def parse_record(values, context, lookup):
    """Validate one 14 field logical record; return ``(published, key, rev, content)``."""
    if len(values) != 14:
        raise Invalid('wrong field count')
    kind = values[0]
    if kind != 'icmp' and kind != 'app':
        raise Invalid('bad type')
    name = values[1]
    if not ident(name):
        raise Invalid('bad record id')
    revision = decimal(values[2], REVISION_MAX)
    published = decimal(values[3], MAX_TIME)
    op = values[4]
    key = (kind, name)
    if op == 'delete':
        if any(values[5:]):
            raise Invalid('delete carries fields')
        return (published, key, revision, DELETE)
    if op != 'put':
        raise Invalid('bad op')
    (lease, event_text, probe, target_text, responder_text, result,
     service, attempt_text, payload_text) = values[5:]
    row = context['leases'].get(lease)
    if row is None:
        raise Invalid('unknown lease')
    event = decimal(event_text, MAX_TIME)
    if event < row['start'] or event >= row['end']:
        raise Invalid('event outside lease')
    if event > published:
        raise Invalid('event after publication')
    target = address(target_text)
    if kind == 'icmp':
        planned = lookup.get((lease, probe))
        if planned is None:
            raise Invalid('unknown probe')
        if target != planned[0]:
            raise Invalid('target is not the planned address')
        if result not in ICMP_RESULTS:
            raise Invalid('bad icmp result')
        if result == 'timeout':
            if responder_text:
                raise Invalid('timeout has a responder')
            responder = None
        else:
            responder = address(responder_text)
        if service or attempt_text or payload_text:
            raise Invalid('icmp put carries application fields')
        return (published, key, revision,
                ('i', lease, event, probe, target, responder, result))
    if probe or responder_text:
        raise Invalid('app put carries icmp fields')
    protocol = context['services'].get(service)
    if protocol is None:
        raise Invalid('unknown service')
    attempt = decimal(attempt_text, ATTEMPT_MAX)
    if result not in APP_RESULTS:
        raise Invalid('bad app result')
    payload = decode64(payload_text, Invalid)
    if len(payload) > PAYLOAD_MAX:
        raise Invalid('oversized payload')
    if result != 'open' and payload:
        raise Invalid('closed or timeout carries a payload')
    if protocol == 'tcp' and payload:
        raise Invalid('tcp carries a payload')
    if result == 'open':
        parsed = TCP_SIGNATURE if protocol == 'tcp' else signature(protocol, payload)
    else:
        parsed = None
    return (published, key, revision,
            ('a', lease, event, target, service, attempt, result, payload, parsed))


class Ledger:
    """Revision-aware visibility of record identities across increasing queries."""

    __slots__ = ('rows', 'index', 'states')

    def __init__(self, records):
        records.sort(key=_published)
        self.rows = records
        self.index = 0
        self.states = {}

    def advance(self, moment):
        """Publish every row with ``published <= moment`` into the identity states."""
        rows = self.rows
        states = self.states
        index = self.index
        total = len(rows)
        while index < total:
            row = rows[index]
            if row[0] > moment:
                break
            index += 1
            key = row[1]
            revision = row[2]
            content = row[3]
            state = states.get(key)
            if state is None:
                states[key] = [revision, {content}]
            elif revision > state[0]:
                state[0] = revision
                state[1] = {content}
            elif revision == state[0]:
                state[1].add(content)
        self.index = index

    def visible(self):
        """Return ``((live, deleted, conflict), icmp_rows, app_rows)`` at this point."""
        live = deleted = conflict = 0
        icmp = []
        app = []
        for state in self.states.values():
            contents = state[1]
            if len(contents) > 1:
                conflict += 1
                continue
            for content in contents:
                break
            marker = content[0]
            if marker == 'd':
                deleted += 1
            elif marker == 'i':
                live += 1
                icmp.append(content)
            else:
                live += 1
                app.append(content)
        return (live, deleted, conflict), icmp, app


def _published(row):
    return row[0]
PYEOF
